/**
 * Tests duplicate headers with the CSVFormat.
 *
 * @param duplicateHeaderMode the duplicate header mode
 * @param allowMissingColumnNames the allow missing column names flag (only used for parsing)
 * @param ignoreHeaderCase the ignore header case flag (only used for parsing)
 * @param headers the headers
 * @param valid true if the settings are expected to be valid, otherwise expect a IllegalArgumentException
 */
@ParameterizedTest
@MethodSource(value = { "duplicateHeaderAllowsMissingColumnsNamesData" })
public void testCSVFormat(final DuplicateHeaderMode duplicateHeaderMode, final boolean allowMissingColumnNames, final boolean ignoreHeaderCase, final String[] headers, final boolean valid) {
    final CSVFormat.Builder builder = CSVFormat.DEFAULT.builder().setDuplicateHeaderMode(duplicateHeaderMode).setAllowMissingColumnNames(allowMissingColumnNames).setIgnoreHeaderCase(ignoreHeaderCase).setHeader(headers);
    if (valid) {
        final CSVFormat format = builder.build();
        Assertions.assertEquals(duplicateHeaderMode, format.getDuplicateHeaderMode(), "DuplicateHeaderMode");
        Assertions.assertEquals(allowMissingColumnNames, format.getAllowMissingColumnNames(), "AllowMissingColumnNames");
        Assertions.assertArrayEquals(headers, format.getHeader(), "Header");
    } else {
        Assertions.assertThrows(IllegalArgumentException.class, builder::build);
    }
}

/**
 * Tests duplicate headers with the CSVParser.
 *
 * @param duplicateHeaderMode the duplicate header mode
 * @param allowMissingColumnNames the allow missing column names flag (only used for parsing)
 * @param ignoreHeaderCase the ignore header case flag (only used for parsing)
 * @param headers the headers (joined with the CSVFormat delimiter to create a string input)
 * @param valid true if the settings are expected to be valid, otherwise expect a IllegalArgumentException
 * @throws IOException Signals that an I/O exception has occurred.
 */
@ParameterizedTest
@MethodSource(value = { "duplicateHeaderData" })
public void testCSVParser(final DuplicateHeaderMode duplicateHeaderMode, final boolean allowMissingColumnNames, final boolean ignoreHeaderCase, final String[] headers, final boolean valid) throws IOException {
    final CSVFormat format = CSVFormat.DEFAULT.builder().setDuplicateHeaderMode(duplicateHeaderMode).setAllowMissingColumnNames(allowMissingColumnNames).setIgnoreHeaderCase(ignoreHeaderCase).setNullString("NULL").setHeader().build();
    final String input = Arrays.stream(headers).map(s -> s == null ? format.getNullString() : s).collect(Collectors.joining(format.getDelimiterString()));
    if (valid) {
        try (CSVParser parser = CSVParser.parse(input, format)) {
            // Parser ignores null headers
            final List<String> expected = Arrays.stream(headers).filter(s -> s != null).collect(Collectors.toList());
            Assertions.assertEquals(expected, parser.getHeaderNames(), "HeaderNames");
        }
    } else {
        Assertions.assertThrows(IllegalArgumentException.class, () -> CSVParser.parse(input, format));
    }
}

@ParameterizedTest
@MethodSource("generateData")
public void testCSVFile(final File testFile) throws Exception {
    try (FileReader fr = new FileReader(testFile);
        BufferedReader testData = new BufferedReader(fr)) {
        String line = readTestData(testData);
        assertNotNull("file must contain config line", line);
        final String[] split = line.split(" ");
        assertTrue(split.length >= 1, testFile.getName() + " require 1 param");
        // first line starts with csv data file name
        CSVFormat format = CSVFormat.newFormat(',').withQuote('"');
        boolean checkComments = false;
        for (int i = 1; i < split.length; i++) {
            final String option = split[i];
            final String[] option_parts = option.split("=", 2);
            if ("IgnoreEmpty".equalsIgnoreCase(option_parts[0])) {
                format = format.withIgnoreEmptyLines(Boolean.parseBoolean(option_parts[1]));
            } else if ("IgnoreSpaces".equalsIgnoreCase(option_parts[0])) {
                format = format.withIgnoreSurroundingSpaces(Boolean.parseBoolean(option_parts[1]));
            } else if ("CommentStart".equalsIgnoreCase(option_parts[0])) {
                format = format.withCommentMarker(option_parts[1].charAt(0));
            } else if ("CheckComments".equalsIgnoreCase(option_parts[0])) {
                checkComments = true;
            } else {
                fail(testFile.getName() + " unexpected option: " + option);
            }
        }
        // get string version of format
        line = readTestData(testData);
        assertEquals(line, format.toString(), testFile.getName() + " Expected format ");
        // Now parse the file and compare against the expected results
        // We use a buffered reader internally so no need to create one here.
        try (final CSVParser parser = CSVParser.parse(new File(BASE_DIR, split[0]), Charset.defaultCharset(), format)) {
            for (final CSVRecord record : parser) {
                String parsed = Arrays.toString(record.values());
                final String comment = record.getComment();
                if (checkComments && comment != null) {
                    parsed += "#" + comment.replace("\n", "\\n");
                }
                final int count = record.size();
                assertEquals(readTestData(testData), count + ":" + parsed, testFile.getName());
            }
        }
    }
}

