@Test
public void testBackslashEscaping() throws IOException {
    // To avoid confusion over the need for escaping chars in java code,
    // We will test with a forward slash as the escape char, and a single
    // quote as the encapsulator.
    final String code = // 0
    "one,two,three\n" + // 1) empty encapsulators
    "'',''\n" + // 2) single encapsulators
    "/',/'\n" + // 3) single encapsulators encapsulated via escape
    "'/'','/''\n" + // 4) single encapsulators encapsulated via doubling
    "'''',''''\n" + // 5) separator escaped
    "/,,/,\n" + // 6) escape escaped
    "//,//\n" + // 7) escape escaped in encapsulation
    "'//','//'\n" + // don't eat spaces
    "   8   ,   \"quoted \"\" /\" // string\"   \n" + // escaped newline
    "9,   /\n   \n" + "";
    final String[][] res = { // 0
    { "one", "two", "three" }, // 1
    { "", "" }, // 2
    { "'", "'" }, // 3
    { "'", "'" }, // 4
    { "'", "'" }, // 5
    { ",", "," }, // 6
    { "/", "/" }, // 7
    { "/", "/" }, { "   8   ", "   \"quoted \"\" /\" / string\"   " }, { "9", "   \n   " } };
    final CSVFormat format = CSVFormat.newFormat(',').withQuote('\'').withRecordSeparator(CRLF).withEscape('/').withIgnoreEmptyLines();
    try (final CSVParser parser = CSVParser.parse(code, format)) {
        final List<CSVRecord> records = parser.getRecords();
        assertFalse(records.isEmpty());
        Utils.compare("Records do not match expected result", res, records);
    }
}

