@Test
public void parse() throws IOException {
    int totcomment = 0;
    int totrecs = 0;
    try (final Reader reader = getTestReader();
        final BufferedReader br = new BufferedReader(reader)) {
        String s = null;
        boolean lastWasComment = false;
        while ((s = br.readLine()) != null) {
            if (s.startsWith("#")) {
                if (!lastWasComment) {
                    // comments are merged
                    totcomment++;
                }
                lastWasComment = true;
            } else {
                totrecs++;
                lastWasComment = false;
            }
        }
    }
    final CSVFormat format = CSVFormat.DEFAULT.builder().// @formatter:off
    setAllowMissingColumnNames(false).setCommentMarker('#').setDelimiter(',').setEscape('\\').setHeader("author", "title", "publishDate").setHeaderComments("headerComment").setNullString("NULL").setIgnoreEmptyLines(true).setIgnoreSurroundingSpaces(true).setQuote('"').setQuoteMode(QuoteMode.ALL).setRecordSeparator('\n').setSkipHeaderRecord(false).build();
    // @formatter:on
    int comments = 0;
    int records = 0;
    try (final Reader reader = getTestReader();
        final CSVParser parser = format.parse(reader)) {
        for (final CSVRecord csvRecord : parser) {
            records++;
            if (csvRecord.hasComment()) {
                comments++;
            }
        }
    }
    // Comment lines are concatenated, in this example 4 lines become 2 comments.
    assertEquals(totcomment, comments);
    // records includes the header
    assertEquals(totrecs, records);
}

