        assertThat(parser.nextToken(new Token()), matches(TOKEN, "trailingTab"));
        assertThat(parser.nextToken(new Token()), matches(TOKEN, "surroundingTabs"));
        assertThat(parser.nextToken(new Token()), matches(TOKEN, ""));
        assertThat(parser.nextToken(new Token()), matches(TOKEN, ""));
        assertThat(parser.nextToken(new Token()), matches(EOF, ""));
    }
}

@Test
public void testTab() throws Exception {
    try (final Lexer lexer = createLexer("character" + TAB + "NotEscaped", formatWithEscaping)) {
        assertThat(lexer.nextToken(new Token()), hasContent("character" + TAB + "NotEscaped"));
    }
}

@Test
public void testTrimTrailingSpacesZeroLength() throws Exception {
    final StringBuilder buffer = new StringBuilder("");
    final Lexer lexer = createLexer(buffer.toString(), CSVFormat.DEFAULT);
    lexer.trimTrailingSpaces(buffer);
    assertThat(lexer.nextToken(new Token()), matches(EOF, ""));
}

@Test
public void testParseBigFileRepeat() throws Exception {
    long bestTime = Long.MAX_VALUE;
    for (int i = 0; i < this.max; i++) {
        bestTime = Math.min(this.testParseBigFile(false), bestTime);
    }
    this.println(String.format("Best time out of %,d is %,d milliseconds.", this.max, bestTime));
}

@Test
public void testReadBigFile() throws Exception {
    long bestTime = Long.MAX_VALUE;
    long count;
    for (int i = 0; i < this.max; i++) {
        final long startMillis;
        try (final BufferedReader in = this.createBufferedReader()) {
            startMillis = System.currentTimeMillis();
            count = this.readAll(in);
        }
        final long totalMillis = System.currentTimeMillis() - startMillis;
        bestTime = Math.min(totalMillis, bestTime);
        this.println(String.format("File read in %,d milliseconds: %,d lines.", totalMillis, count));
    }
    this.println(String.format("Best time out of %,d is %,d milliseconds.", this.max, bestTime));
}

@Test
public void testHasContent() {
    assertFalse(hasContent("This is not the token's content").matches(token));
    assertTrue(hasContent("content").matches(token));
}

@Test
public void testHasType() {
    assertFalse(hasType(Token.Type.COMMENT).matches(token));
    assertFalse(hasType(Token.Type.EOF).matches(token));
    assertFalse(hasType(Token.Type.EORECORD).matches(token));
    assertTrue(hasType(Token.Type.TOKEN).matches(token));
}

@Test
public void testIsReady() {
    assertTrue(isReady().matches(token));
    token.isReady = false;
    assertFalse(isReady().matches(token));
}

@Test
public void testMatches() {
    assertTrue(matches(Token.Type.TOKEN, "content").matches(token));
    assertFalse(matches(Token.Type.EOF, "content").matches(token));
    assertFalse(matches(Token.Type.TOKEN, "not the content").matches(token));
    assertFalse(matches(Token.Type.EORECORD, "not the content").matches(token));
}

@Test
public void testToString() {
    assertTrue(matches(Token.Type.TOKEN, "content").matches(token));
    assertEquals("TOKEN", token.type.name());
    assertEquals("TOKEN [content]", token.toString());
}
